 else if(scan_){auto n=scan_->advanceBefore(cost,cr,[&](bool buttons,unsigned row){return read(buttons?0xffffc7:0xc1c8+row,1,cost);},[&](S::Write field,unsigned value){write(field==S::Write::Direction?0xffffc5:field==S::Write::Select?0xffffd3:0xc1c8+scan_->row(),value,1,cost);});if(n!=cost)return {};if(scan_->awaiting())map_.emplace(scan_->event());if(scan_->complete()){scan_.reset();if(reset_)reset_->resume();else active_=false;}}
 else if(resetChild_){auto n=resetChild_->advanceBefore(cost,cr,[&](bool head,unsigned v){write(head?0xc144:0xc146,v,2,cost);});if(n!=cost)return {};if(resetChild_->complete()){resetChild_.reset();reset_->resume();}}
 else if(reset_){auto stage=reset_->stage();auto n=reset_->advanceBefore(cost,cr,[&](bool head,unsigned v){write(head?0xc144:0xc146,v,2,cost);});if(n!=cost)return {};if(reset_->awaiting()){if(stage==RS::Scan)scan_.emplace();else resetChild_.emplace(false);}if(reset_->complete()){reset_.reset();active_=false;}}
